import json
from pathlib import Path
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
p=Path('examples/KG_Assoc/kg_assoc_100m/aggregate/e2/review_dfe53f8405f34163ba9d344dcad5a0df/summary.json')
s=json.loads(p.read_text())
names=('intra','mean_degree','mean_rg2','mean_center_terminal_r2')
fig,axes=plt.subplots(4,3,figsize=(12,9),sharex=True,sharey='row')
for col,r in enumerate(s['records']):
 t=[(w['start_step_exclusive']+w['end_step_inclusive'])/2e6 for w in r['windows']]
 for row,name in enumerate(names):
  ax=axes[row,col];ax.plot(t,[w['metrics'][name]['mean'] for w in r['windows']],'-o',ms=3)
  ax.axvspan(0,1,color='gray',alpha=.15)
  for step in (2,4,6):ax.axvline(step,color='gray',ls=':',lw=.7)
  if col==0:ax.set_ylabel(name)
  if row==0:ax.set_title(f"r{r['replica']:03d}")
  if row==3:ax.set_xlabel('absolute MD steps / million')
fig.suptitle('N=40: 500k window means; three independent histories\nShading: initial transient. Vertical markers are analysis boundaries, not restarts.')
fig.tight_layout();fig.savefig('/tmp/n40_paths.png',dpi=150)
